-- Incolla in Supabase -> SQL Editor -> New query e premi Run. Si puo' rilanciare senza problemi.
update public.contenuti set dati = jsonb_set(jsonb_set(dati, '{_seo}', coalesce(dati->'_seo','{}'::jsonb) || '{"titolo": "Gestione affitti brevi e immobili Lago di Como e Valtellina | LA MAISON GROUP", "descrizione": "Gestione affitti brevi, affitti e vendita di immobili sul Lago di Como, in Valchiavenna e Valtellina, nelle province di Sondrio, Como, Lecco, Bergamo e a Torino. Valutazione gratuita."}'::jsonb), '{dove_operiamo,testo_1}', '"Seguiamo di persona gli immobili sul Lago di Como, in Valchiavenna e Valtellina e nelle altre province evidenziate sulla mappa. Il tuo immobile si trova altrove? Scrivici: valutiamo ogni richiesta."'::jsonb), aggiornato = now() where percorso = 'data/pagine/index.json';
update public.contenuti set dati = jsonb_set(jsonb_set(dati, '{_seo}', coalesce(dati->'_seo','{}'::jsonb) || '{"titolo": "Short-term rental management Lake Como and Valtellina | LA MAISON GROUP", "descrizione": "Short-term rental management, rentals and property sales on Lake Como, in Valchiavenna and Valtellina, in the provinces of Sondrio, Como, Lecco, Bergamo and in Turin. Free valuation."}'::jsonb), '{dove_operiamo,testo_1}', '"We personally manage properties on Lake Como, in Valchiavenna and Valtellina and in the other provinces highlighted on the map. Is your property somewhere else? Get in touch: we consider every request."'::jsonb), aggiornato = now() where percorso = 'data/pagine/en/index.json';
